// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import * as d3 from 'd3';
import { useEffect, useMemo, useState } from 'react';

// ---- inlined from relaxation ----
/**
 * Traces for Lloyd relaxation and k-means, one module because k-means IS Lloyd's
 * algorithm over a fixed point set: both alternate assign-to-nearest-site with
 * move-site-to-centroid; only what moves differs — Lloyd relaxes the points
 * themselves, k-means holds the points still and relaxes the cluster centres.
 */


const RELAX_ASPECT = 0.62;
const SEED_LLOYD = 20260821;
const SEED_KMEANS = 20260822;

/** mulberry32: a fixed seed keeps every run identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ------------------------------------------------------------------ Lloyd relaxation

const LLOYD_N = 60;
const LLOYD_ITERATIONS = 40;

interface LloydFrame {
  /** Site positions after this many relaxation steps, in [0,1] x [0,RELAX_ASPECT]. */
  points: [number, number][];
  /** Largest site displacement entering this frame, 0 for the initial scatter. */
  maxMove: number;
}

const lloydFrames: LloydFrame[] = (() => {
  const random = seededRandom(SEED_LLOYD);
  let points: [number, number][] = Array.from({ length: LLOYD_N }, () => [
    random(),
    random() * RELAX_ASPECT
  ]);
  const frames: LloydFrame[] = [{ points, maxMove: 0 }];

  for (let k = 0; k < LLOYD_ITERATIONS; ++k) {
    const voronoi = d3.Delaunay.from(points).voronoi([0, 0, 1, RELAX_ASPECT]);
    let maxMove = 0;
    points = points.map(([x, y], i) => {
      const cell = voronoi.cellPolygon(i);
      if (!cell) return [x, y];
      const [cx, cy] = d3.polygonCentroid(cell);
      maxMove = Math.max(maxMove, Math.hypot(cx - x, cy - y));
      return [cx, cy];
    });
    frames.push({ points, maxMove });
  }

  return frames;
})();

// ------------------------------------------------------------------ k-means

const KM_K = 5;
const KM_PER_BLOB = 34;
const KM_SPREAD = 0.095;
const KM_MAX_ROUNDS = 25;

const kmeansPoints: [number, number][] = [];

interface KmeansFrame {
  phase: 'assign' | 'update';
  /** Cluster index per point; during an update frame this is the previous assignment. */
  assign: number[];
  centroids: [number, number][];
  /** How many points switched cluster on this assign frame; 0 announces equilibrium. */
  changed: number;
}

const kmeansFrames: KmeansFrame[] = (() => {
  const random = seededRandom(SEED_KMEANS);
  const gauss = () => {
    const u = Math.max(random(), 1e-9);
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
  };
  const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

  const centers: [number, number][] = Array.from({ length: KM_K }, () => [
    0.14 + 0.72 * random(),
    RELAX_ASPECT * (0.16 + 0.68 * random())
  ]);
  for (const [cx, cy] of centers) {
    for (let i = 0; i < KM_PER_BLOB; ++i) {
      kmeansPoints.push([
        clamp(cx + KM_SPREAD * gauss(), 0.01, 0.99),
        clamp(cy + KM_SPREAD * gauss(), 0.01, RELAX_ASPECT - 0.01)
      ]);
    }
  }

  let centroids: [number, number][] = Array.from({ length: KM_K }, () => [
    0.1 + 0.8 * random(),
    RELAX_ASPECT * (0.1 + 0.8 * random())
  ]);
  let assign = new Array<number>(kmeansPoints.length).fill(-1);
  const frames: KmeansFrame[] = [];

  for (let round = 0; round < KM_MAX_ROUNDS; ++round) {
    let changed = 0;
    assign = kmeansPoints.map(([x, y], i) => {
      let best = 0;
      let bestDistance = Infinity;
      centroids.forEach(([cx, cy], c) => {
        const distance = (x - cx) ** 2 + (y - cy) ** 2;
        if (distance < bestDistance) {
          bestDistance = distance;
          best = c;
        }
      });
      if (best !== assign[i]) ++changed;
      return best;
    });
    frames.push({ phase: 'assign', assign, centroids, changed });
    if (changed === 0) break;

    centroids = centroids.map((centroid, k) => {
      const mine = kmeansPoints.filter((_, i) => assign[i] === k);
      if (!mine.length) return centroid;
      return [d3.mean(mine, (p) => p[0]) as number, d3.mean(mine, (p) => p[1]) as number];
    });
    frames.push({ phase: 'update', assign, centroids, changed });
  }

  return frames;
})();

const TICK_MS = 280;
const HOLD_TICKS = 14;
const LAST = lloydFrames.length - 1;
const MOVE = '#e0538a';

export default function LloydRelaxation({ width }: { width: number }) {
  const safeWidth = Math.max(1, width);
  const gridHeight = Math.round(safeWidth * RELAX_ASPECT);
  const height = gridHeight + 20;

  // The SSR frame is the settled tessellation; the effect rewinds and replays relaxation.
  const [step, setStep] = useState(LAST);

  useEffect(() => {
    const end = LAST + HOLD_TICKS;
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= end ? 0 : s + 1)), TICK_MS);
    return () => window.clearInterval(id);
  }, []);

  const shown = Math.min(step, LAST);

  const scaled = useMemo(
    () =>
      lloydFrames.map(({ points }) =>
        points.map(([x, y]): [number, number] => [x * safeWidth, y * safeWidth])
      ),
    [safeWidth]
  );

  const { mesh, sites } = useMemo(() => {
    const delaunay = d3.Delaunay.from(scaled[shown]);
    return {
      mesh: delaunay.voronoi([0, 0, safeWidth, gridHeight]).render(),
      sites: delaunay.renderPoints(undefined, Math.max(1.5, safeWidth * 0.0038))
    };
  }, [scaled, shown, safeWidth, gridHeight]);

  /** Each site's jump into this frame — long early, a tremble late. */
  const whiskers = useMemo(() => {
    if (shown === 0) return '';
    const previous = scaled[shown - 1];
    return scaled[shown]
      .map(([x, y], i) => `M${previous[i][0].toFixed(1)},${previous[i][1].toFixed(1)}L${x.toFixed(1)},${y.toFixed(1)}`)
      .join('');
  }, [scaled, shown]);

  if (width === 0) return null;

  const movePx = lloydFrames[shown].maxMove * safeWidth;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Lloyd relaxation of sixty seeded points toward a centroidal Voronoi tessellation: every iteration each site jumps to its cell's centroid, and the displacement whiskers shrink from early leaps to late trembles as the cells settle into an even honeycomb"
    >
      <path d={mesh} fill="none" stroke="var(--line)" strokeWidth={1} />
      <path d={whiskers} fill="none" stroke={MOVE} strokeWidth={1.4} strokeLinecap="round" />
      <path d={sites} fill="var(--accent)" />
      <text x={4} y={height - 6} fill="var(--muted)" fontSize={11}>
        {shown === 0
          ? `${LLOYD_N} points, initial scatter`
          : `iteration ${shown} of ${LAST} · max move ${movePx.toFixed(1)}px`}
      </text>
    </svg>
  );
}
